// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

export interface AdmissionDetailOut {
  admission_id: number;
  admission_number: string;
  patient_id: number;
  /** The newest Patient Photo of the merge chain, for the identity check; null when none was taken (it is optional). GET /patient-documents/{document_id}/download */
  photo_document_id: number | null;
  mrn: string;
  patient_name: string;
  gender: "male" | "female" | "other" | "unknown" | null;
  age_years: number | null;
  requested_ward_id: number | null;
  requested_ward_name: string | null;
  ward_id: number | null;
  ward_name: string | null;
  bed_id: number | null;
  bed_label: string | null;
  /** The treating doctor's employee id; null for a Code Red no doctor has taken over yet (decisions 57): show 'Doctor: waiting' */
  primary_doctor_id: number | null;
  primary_doctor_name: string | null;
  admission_type: "Standard" | "Emergency" | "CodeRed" | "Overflow" | "Planned";
  status: "AdmissionPending" | "Waitlisted" | "BedReserved" | "CodeRedActive" | "Admitted" | "DischargeInProgress" | "Discharged" | "Cancelled";
  billing_category: "Cash" | "Panel";
  panel_id: number | null;
  is_billing_confirmed: boolean;
  is_billing_deferred: boolean;
  is_overflow: boolean;
  overflow_reason: string | null;
  eta_minutes: number | null;
  source_ticket_id: number | null;
  /** Why the patient was admitted (MSDS 149); null only on a Code Red admission not yet recorded */
  admission_reason: string | null;
  provisional_diagnosis: string | null;
  initial_care_plan: string | null;
  /** Who recorded the reason and diagnosis, and when (MSDS 147) */
  details_stamp: AuthorStampOut | null;
  /** For the admissions desk (not clinical) */
  admission_notes: string | null;
  requested_at: string;
  reserved_at: string | null;
  admitted_at: string | null;
  discharge_initiated_at: string | null;
  discharged_at: string | null;
  row_version: number;
  discharge: DischargeStatusOut;
  /** The running IPD bill */
  invoice: AdmissionInvoiceOut | null;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

export interface DischargeStatusOut {
  stages: DischargeStageOut[];
  /** The first pending stage (the one to clear next) */
  blocked_on: "ClinicalDischarge" | "PharmacyClearance" | "NursingMARVerification" | "BillingSettlement" | "OpsCleaning" | null;
  started: boolean;
  complete: boolean;
}

export interface DischargeStageOut {
  clearance_id: number;
  stage: "ClinicalDischarge" | "PharmacyClearance" | "NursingMARVerification" | "BillingSettlement" | "OpsCleaning";
  sequence_no: number;
  status: "Pending" | "Cleared" | "Cancelled";
  cleared_by: number | null;
  cleared_by_name: string | null;
  cleared_at: string | null;
  note: string | null;
  physically_cleaned_at: string | null;
}

export interface AdmissionInvoiceOut {
  invoice_id: number;
  invoice_no: string;
  status: "Draft" | "Open" | "PartiallyPaid" | "Paid" | "CreditAuthorized" | "Waivered" | "Refunded" | "Cancelled";
  gross_total: number;
  net_payable: number | null;
  amount_paid: number;
}

/** Admission with bed, discharge stage and bill — GET /api/v1/admissions/{admission_id} (who may call: holders of ipd.admission.view). */
export function getAdmission(admission_id: number): Promise<AdmissionDetailOut> {
  return api<AdmissionDetailOut>("GET", `/admissions/${admission_id}`, undefined);
}
